  const importJsonFile = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) {
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const raw = e.target?.result as string;
        const model = JSON.parse(raw) as FloorPlanModel;
        if (model.rooms) {
          model.rooms = model.rooms.filter((r) => !r.id.startsWith(ROOM_AUTO_ID_PREFIX));
        }
        history.set({
          ...initialModel,
          ...model,
          walls: splitWallsAtIntersections(model.walls ?? []),
        });
        // Clear the input so the same file can be imported again
        event.target.value = "";
      } catch (err) {
        console.error("Failed to parse floorplan JSON", err);
      }
    };
    reader.readAsText(file);
  };

  const importVestalJson = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) {
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(String(reader.result));
        const boundary = data.boundary as [number, number][];
        const rooms = data.rooms as RoomConstraint[];
        const connections = data.connections as [string, string][];

        if (!boundary || boundary.length < 3) {
          throw new Error("Invalid boundary");
        }

        const newWalls: Wall[] = [];
        for (let i = 0; i < boundary.length - 1; i++) {
          const startArr = boundary[i];
          const endArr = boundary[i + 1];
          newWalls.push({
            id: createId(),
            start: { x: startArr[0], y: startArr[1] },
            end: { x: endArr[0], y: endArr[1] },
            thickness: layerVisibility.viewGraph ? 0.01 : wallThickness,
            color: wallColor,
            mode: wallDrawMode,
            method: wallDrawMethod,
          });
        }

        history.set({
          ...initialModel,
          walls: splitWallsAtIntersections(newWalls),
          constraints: {
            rooms,
            connections,
          },
        });

        // Center the view on the new boundary
        const minX = Math.min(...boundary.map(p => p[0]));
        const maxX = Math.max(...boundary.map(p => p[0]));
        const minY = Math.min(...boundary.map(p => p[1]));
        const maxY = Math.max(...boundary.map(p => p[1]));
        const centerX = (minX + maxX) / 2;
        const centerY = (minY + maxY) / 2;

        if (size.width > 0 && size.height > 0) {
          setPosition({
            x: size.width / 2 - centerX * scale,
            y: size.height / 2 - centerY * scale,
          });
        }

      } catch (error) {
        console.error("Invalid Vestal JSON", error);
      }
    };
    reader.readAsText(file);
  };

